<?php
if (!defined('ABSPATH')) { exit; }

/** Teacher-scoped listing of only confirmed and moderator-published category results. */
class ZMP_Mentor_Category_Results {
    public static function render() {
        if (!is_user_logged_in() || (!current_user_can('zmp_teacher_cap') && !current_user_can('view_zmp_teacher_dashboard'))) { return ''; }
        global $wpdb; $uid=get_current_user_id();
        $names=array('year'=>'zmp_cat_result_year','category'=>'zmp_cat_result_category','group'=>'zmp_cat_result_group','phase'=>'zmp_cat_result_phase','region'=>'zmp_cat_result_region','municipality'=>'zmp_cat_result_municipality','school'=>'zmp_cat_result_school','education'=>'zmp_cat_result_education','track'=>'zmp_cat_result_track');
        $v=array();foreach($names as $key=>$name){$raw=$_GET[$name]??'';$v[$key]=is_scalar($raw)?sanitize_text_field(wp_unslash($raw)):'';}
        $v['category']=absint($v['category']);
        if(!in_array($v['phase'],array('','municipal','regional','state'),true))$v['phase']='';
        if(!ZMP_Regions::valid_region($v['region']))$v['region']='';
        if(!in_array($v['education'],array('','primary','secondary'),true))$v['education']='';
        if(!in_array($v['track'],array('','gymnasium','vocational'),true))$v['track']='';
        $where=array("(e.wp_user_id=%d OR e.mentor_id IN (SELECT id FROM {$wpdb->prefix}zmp_mentors WHERE wp_user_id=%d))","f.status='confirmed'","c.category_code<>'knowledge_test'","EXISTS (SELECT 1 FROM {$wpdb->prefix}zmp_announcements a WHERE a.kind='results' AND a.status='published' AND a.academic_year=s.academic_year AND a.category_id=f.category_id AND a.phase=f.phase)");$args=array($uid,$uid);
        $map=array('year'=>array('s.academic_year','%s'),'category'=>array('f.category_id','%d'),'group'=>array('g.name_mk','%s'),'phase'=>array('f.phase','%s'),'region'=>array('e.region','%s'),'municipality'=>array('e.municipality','%s'),'school'=>array('e.school_name','LIKE'),'education'=>array('g.education_level','%s'),'track'=>array('g.school_track','%s'));
        foreach($map as $key=>$rule){if($v[$key]===''||$v[$key]===0)continue;$where[]=$rule[1]==='LIKE'?$rule[0].' LIKE %s':$rule[0].'='.$rule[1];$args[]=$rule[1]==='LIKE'?'%'.$wpdb->esc_like($v[$key]).'%':($rule[1]==='%d'?absint($v[$key]):$v[$key]);}
        $sql="SELECT f.id result_id,e.id entry_id,e.participant_name,e.school_name,e.municipality,e.region,s.academic_year,c.name_mk category_name,g.name_mk group_name,g.education_level,g.school_track,f.phase,f.final_points,f.award_key,f.decided_at FROM {$wpdb->prefix}zmp_category_final_results f JOIN {$wpdb->prefix}zmp_category_entries e ON e.id=f.entry_id AND e.season_id=f.season_id AND e.category_id=f.category_id JOIN {$wpdb->prefix}zmp_seasons s ON s.id=f.season_id JOIN {$wpdb->prefix}zmp_categories c ON c.id=f.category_id LEFT JOIN {$wpdb->prefix}zmp_category_groups g ON g.id=e.group_id WHERE ".implode(' AND ',$where)." ORDER BY s.academic_year DESC,c.sort_order,g.sort_order,e.school_name,e.participant_name,f.phase";
        $rows=(array)$wpdb->get_results($wpdb->prepare($sql,$args));
        $years=$wpdb->get_col($wpdb->prepare("SELECT DISTINCT s.academic_year FROM {$wpdb->prefix}zmp_category_final_results f JOIN {$wpdb->prefix}zmp_category_entries e ON e.id=f.entry_id JOIN {$wpdb->prefix}zmp_seasons s ON s.id=f.season_id JOIN {$wpdb->prefix}zmp_categories c ON c.id=f.category_id WHERE (e.wp_user_id=%d OR e.mentor_id IN (SELECT id FROM {$wpdb->prefix}zmp_mentors WHERE wp_user_id=%d)) AND f.status='confirmed' AND c.category_code<>'knowledge_test' ORDER BY s.academic_year DESC",$uid,$uid));
        $categories=$wpdb->get_results("SELECT id,name_mk FROM {$wpdb->prefix}zmp_categories WHERE is_active=1 AND category_code<>'knowledge_test' ORDER BY sort_order,id");$groups=$wpdb->get_results("SELECT name_mk FROM {$wpdb->prefix}zmp_category_groups WHERE is_active=1 GROUP BY name_mk ORDER BY MIN(sort_order),name_mk");$url=remove_query_arg(array_values($names));
        ob_start(); ?>
        <section class="zmp-card zmp-mentor-category-results"><h4>Резултати од музичките категории</h4><p>Се прикажуваат само конечни резултати што ги потврдила комисијата и ги објавил модераторот, за вашите пријави.</p>
        <form method="get" action="<?php echo esc_url($url); ?>" class="zmp-filter-bar">
        <?php foreach($_GET as $key=>$value){if(is_scalar($value)&&!in_array($key,array_values($names),true))echo '<input type="hidden" name="'.esc_attr(sanitize_key($key)).'" value="'.esc_attr(wp_unslash($value)).'">';} ?><input type="hidden" name="zmp_mentor_tab" value="results">
        <label>Година <select name="zmp_cat_result_year"><option value="">Сите</option><?php foreach((array)$years as $year): ?><option value="<?php echo esc_attr($year); ?>" <?php selected($v['year'],$year); ?>><?php echo esc_html($year); ?></option><?php endforeach; ?></select></label>
        <label>Категорија <select name="zmp_cat_result_category"><option value="">Сите</option><?php foreach((array)$categories as $c): ?><option value="<?php echo (int)$c->id; ?>" <?php selected($v['category'],(int)$c->id); ?>><?php echo esc_html($c->name_mk); ?></option><?php endforeach; ?></select></label>
        <label>Група <select name="zmp_cat_result_group"><option value="">Сите</option><?php foreach((array)$groups as $g): ?><option value="<?php echo esc_attr($g->name_mk); ?>" <?php selected($v['group'],$g->name_mk); ?>><?php echo esc_html($g->name_mk); ?></option><?php endforeach; ?></select></label>
        <label>Натпреварувачко ниво <select name="zmp_cat_result_phase"><option value="">Сите</option><option value="municipal" <?php selected($v['phase'],'municipal'); ?>>Општинско натпреварувачко ниво</option><option value="regional" <?php selected($v['phase'],'regional'); ?>>Регионално натпреварувачко ниво</option><option value="state" <?php selected($v['phase'],'state'); ?>>Државно натпреварувачко ниво</option></select></label>
        <label>Регион <select name="zmp_cat_result_region"><option value="">Сите</option><?php foreach(ZMP_Regions::regions() as $key=>$region): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($v['region'],$key); ?>><?php echo esc_html($region['label']); ?></option><?php endforeach; ?></select></label>
        <label>Општина <input name="zmp_cat_result_municipality" value="<?php echo esc_attr($v['municipality']); ?>"></label><label>Училиште <input name="zmp_cat_result_school" value="<?php echo esc_attr($v['school']); ?>"></label>
        <label>Ниво <select name="zmp_cat_result_education"><option value="">Сите</option><option value="primary" <?php selected($v['education'],'primary'); ?>>Основно</option><option value="secondary" <?php selected($v['education'],'secondary'); ?>>Средно</option></select></label><label>Средно образование <select name="zmp_cat_result_track"><option value="">Сите</option><option value="gymnasium" <?php selected($v['track'],'gymnasium'); ?>>Гимназиско</option><option value="vocational" <?php selected($v['track'],'vocational'); ?>>Стручно</option></select></label><button class="zmp-btn zmp-btn-primary">Филтрирај</button></form>
        <div class="zmp-table-responsive"><table class="zmp-table"><thead><tr><th scope="col">Учесник / состав</th><th scope="col">Категорија</th><th scope="col">Група</th><th scope="col">Година / натпреварувачко ниво</th><th scope="col">Училиште</th><th scope="col">Општина / регион</th><th scope="col">Поени</th><th scope="col">Награда</th><th scope="col">Диплома</th></tr></thead><tbody>
        <?php if(!$rows): ?><tr><td colspan="9">Нема објавени резултати за вашите пријави и избраните филтри.</td></tr><?php else: foreach($rows as $row): ?><tr><td><?php echo esc_html($row->participant_name); ?></td><td><?php echo esc_html($row->category_name); ?></td><td><?php echo esc_html($row->group_name); ?></td><td><?php echo esc_html($row->academic_year.' / '.ZMP_Category_Jury::phase_label($row->phase)); ?></td><td><?php echo esc_html($row->school_name); ?></td><td><?php echo esc_html($row->municipality.' / '.ZMP_Regions::label($row->region)); ?></td><td><?php echo esc_html(number_format((float)$row->final_points,2,',','')); ?></td><td><?php echo esc_html((array('first'=>'Прва награда','second'=>'Втора награда','third'=>'Трета награда','honorable'=>'Пофалница')[$row->award_key]??'')); ?></td><td><?php echo class_exists('ZMP_Governance')?ZMP_Governance::render_entry_certificates((int)$row->entry_id):'—'; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
        <?php return ob_get_clean();
    }
}